// frontend/src/features/dashboard/organizer/OrganizerDashboard.jsx
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const OrganizerDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchEvents = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/organizer/my-events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(response.data.events);
      setLoading(false);
      setError(null);
    } catch (err) {
      setError('Failed to fetch events');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
    const intervalId = setInterval(fetchEvents, 30000); // refresh every 30s
    return () => clearInterval(intervalId);
  }, []);

  return (
    <div className="container">
      <div className="card">
        <h2>Organizer Dashboard</h2>
        <p>Manage your events, view ticket sales, and track performance.</p>

        {/* Event Management Section */}
        <section>
          <h3>Event Management</h3>

          <Link to="/organizer/create-event">
            <button className="btn" style={{ marginRight: '1rem' }}>
              Create New Event
            </button>
          </Link>

          <Link to="/organizer/my-events">
            <button className="btn">
              Manage Events
            </button>
          </Link>

          <div style={{ marginTop: '1rem' }}>
            <h4>Your Events</h4>
            {loading ? (
              <p>Loading events...</p>
            ) : error ? (
              <p style={{ color: 'red' }}>{error}</p>
            ) : events.length > 0 ? (
              <ul>
                {events.map(event => (
                  <li key={event._id} style={{ marginBottom: '0.5rem' }}>
                    <strong>{event.title}</strong> | Date: {new Date(event.date).toLocaleDateString()}<br />
                    Registrations: {event.registrations || 0} | Revenue: ₹{event.ticketSales || 0}
                  </li>
                ))}
              </ul>
            ) : (
              <p>No events found.</p>
            )}
          </div>
        </section>

        {/* Analytics & Insights Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Analytics & Insights</h3>
          <p>Total Events: {events.length}</p>
          <p>Total Registrations: {events.reduce((acc, e) => acc + (e.registrations || 0), 0)}</p>
          <p>Total Revenue: ₹{events.reduce((acc, e) => acc + (e.ticketSales || 0), 0)}</p>
        </section>

        {/* Notifications & Updates Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Notifications & Updates</h3>
          <button className="btn">Send Update to Attendees</button>
        </section>
      </div>
    </div>
  );
};

export default OrganizerDashboard;
